package com.campusplacement.controller;
import com.campusplacement.dto.ApiResponse; import com.campusplacement.entity.*; import com.campusplacement.repository.InterviewRepository; import com.campusplacement.service.PlacementService; import org.springframework.web.bind.annotation.*; import java.util.*; import java.util.stream.*;
@RestController @RequestMapping("/interviews")
public class InterviewController { private final InterviewRepository repo; private final PlacementService service; public InterviewController(InterviewRepository r,PlacementService s){repo=r;service=s;}
 private Map<String,Object> view(Interview i){Map<String,Object> m=new LinkedHashMap<>();m.put("id",i.getId());m.put("applicationId",i.getApplication().getId());m.put("studentId",i.getStudent().getId());m.put("student",i.getStudent().getName());m.put("rollNumber",i.getStudent().getRollNumber());m.put("company",i.getDrive().getCompany().getName());m.put("role",i.getDrive().getJobRole());m.put("driveId",i.getDrive().getId());m.put("round",i.getRound());m.put("interviewDate",i.getInterviewDate());m.put("interviewTime",i.getInterviewTime());m.put("venue",i.getVenue());m.put("meetingLink",i.getMeetingLink());m.put("type",i.getType());m.put("status",i.getStatus());return m;}
 @GetMapping public List<Map<String,Object>> all(){return repo.findAll().stream().map(this::view).collect(Collectors.toList());}
 @PostMapping public ApiResponse create(@RequestBody Map<String,String> body){return new ApiResponse(true,"Interview scheduled",view(service.schedule(body)));}
 @PostMapping("/preview") public List<Map<String,Object>> preview(@RequestBody Map<String,Object> body){return service.previewInterviewStudents(body).stream().map(s->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",s.getId());m.put("rollNumber",s.getRollNumber());m.put("name",s.getName());m.put("department",s.getDepartment());return m;}).collect(Collectors.toList());}
 @PostMapping("/bulk") public ApiResponse bulk(@RequestBody Map<String,Object> body){List<Interview> saved=service.bulkSchedule(body);return new ApiResponse(true,"Bulk interview scheduling completed for "+saved.size()+" student(s)",saved.stream().map(this::view).collect(Collectors.toList()));}
 @PutMapping("/{id}/status") public ApiResponse status(@PathVariable Integer id,@RequestParam String value){Interview i=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Interview not found"));if(!Arrays.asList("SCHEDULED","ATTEMPTED","COMPLETED","CANCELLED").contains(value.toUpperCase()))throw new IllegalArgumentException("Invalid interview status");String status=value.toUpperCase();i.setStatus(status);if(i.getApplication()!=null){i.getApplication().setStatus("SCHEDULED".equals(status)?"INTERVIEW_SCHEDULED":("CANCELLED".equals(status)?"INTERVIEW_NOT_SCHEDULED":i.getApplication().getStatus()));}return new ApiResponse(true,"Interview status updated",view(repo.save(i)));}
}
